import { useCallback, useState } from 'react';
import { Document, Page } from 'react-pdf';

import { Skeleton } from 'components';

import { TrainingContentType } from '../../domain';

interface MediaViewerProps {
  media: string;
  type: TrainingContentType;
  title: string;
}

interface DocumentLoadSuccessEvent {
  numPages: number;
}

const PAGE_HEIGHT = 707;
const PAGE_WIDTH = 1256;

const renderSkeleton = () => {
  return (
    <Skeleton
      width={`${PAGE_WIDTH}px`}
      height={`${PAGE_HEIGHT}px`}
      length={1}
    />
  );
};

const renderDocument = (
  media: string,
  numPages: number,
  onDocumentLoadSuccess: (event: DocumentLoadSuccessEvent) => void,
) => {
  return (
    <Document
      file={media}
      onLoadSuccess={onDocumentLoadSuccess}
      loading={renderSkeleton()}
      error={<span>Failed to load PDF.</span>}
    >
      <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
        {Array.from({ length: numPages }, (_, index) => (
          <Page
            key={index}
            pageNumber={index + 1}
            renderTextLayer
            renderAnnotationLayer
            width={PAGE_WIDTH}
            height={PAGE_HEIGHT}
          />
        ))}
      </div>
    </Document>
  );
};

const renderVideo = (media: string, title: string) => {
  return (
    <iframe
      style={{ width: PAGE_WIDTH, height: PAGE_HEIGHT }}
      src={media}
      title={title}
      frameBorder="0"
      allowFullScreen
    />
  );
};

export const MediaViewer: React.FC<MediaViewerProps> = ({
  media,
  type,
  title,
}) => {
  const [numPages, setNumPages] = useState<number>(0);

  const onDocumentLoadSuccess = useCallback(
    ({ numPages: total }: DocumentLoadSuccessEvent) => {
      setNumPages(total);
    },
    [],
  );

  if (type === 'video') {
    return renderVideo(media, title);
  }
  if (type === 'document') {
    return renderDocument(media, numPages, onDocumentLoadSuccess);
  }
  return null;
};
